create or replace function public.create_organization(org_name text, org_slug text) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'not authenticated'; end if; if length(trim(org_name))<2 or length(trim(org_slug))<2 then raise exception 'invalid organization'; end if; insert into public.organizations(name,slug) values(trim(org_name),lower(trim(org_slug))) returning id into new_id; insert into public.organization_members(organization_id,user_id,role,status,joined_at) values(new_id,auth.uid(),'OWNER','ACTIVE',now()); return new_id; end; $$;
revoke all on function public.create_organization(text,text) from public;
grant execute on function public.create_organization(text,text) to authenticated;
